// Native request replay proves UI; session projection below is an adapter, not live networking.
public static class VariableBranchPresentationValidation
{
    const string Base=".tools/variable-branches-1006/ui",Native=".tools/variable-branches-1006/native";
    static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    public static string Output {get;private set;}
    public static bool Running {get;private set;}
    [Serializable] class Meta {public string folder,status,runtimeHash;}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string file){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(file))).Replace("-","").ToLowerInvariant();}
    static string Folder(string name){var p=Native+"/"+name+"-result.json";var m=JsonUtility.FromJson<Meta>(File.ReadAllText(p));Check(m.status=="PASS"&&m.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Incomplete/stale native "+name);File.Copy(p,Output+"/inputs/"+name+"-meta.json",true);return m.folder;}
    static ForgeSeatView Read(string name,string label){string p=Path.Combine(Folder(name),label+".json");File.Copy(p,Output+"/inputs/"+name+"-"+label+".json",true);File.AppendAllText(Output+"/input-hashes.tsv",name+"/"+label+"\t"+Hash(p)+"\n");return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
    static ForgeSeatView Request(string name,Func<ForgeRequest,bool> match){foreach(string p in Directory.GetFiles(Folder(name),"step-*.json").Where(p=>!p.EndsWith("-other.json")).OrderBy(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Substring(5)))){var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));if(match(v.request))return Read(name,Path.GetFileNameWithoutExtension(p)+(v.request.seat==2?"-other":""));}throw new Exception("No native request "+name);}
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    static void Clean(){foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}}
    static void Click(Button button){Check(button!=null&&button.interactable,"Missing/disabled "+button?.name);var rect=(RectTransform)button.transform;foreach(float y in new[]{.5f,.25f,.75f})foreach(float x in new[]{.5f,.12f,.88f}){var local=new Vector2(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,x),Mathf.Lerp(rect.rect.yMin,rect.rect.yMax,y));var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(local)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);if(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==button){ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);return;}}throw new Exception("Ray blocked "+button.name);}
    static Rect Bounds(Transform t){var c=new Vector3[4];((RectTransform)t).GetWorldCorners(c);return Rect.MinMaxRect(c.Min(p=>p.x),c.Min(p=>p.y),c.Max(p=>p.x),c.Max(p=>p.y));}
    static void DockBounds(Transform dock){foreach(var b in dock.GetComponentsInChildren<Button>()){Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("CornerCluster/ControlRow/PhaseTrack"))),"Phase covered");Check(!Bounds(b.transform).Overlaps(Bounds(Root.Find("PriorityControlMode"))),"AUTO covered");}}
    static IEnumerator Shot(string lang,string label){if(lang!="zh-CN")yield break;ScreenCapture.CaptureScreenshot(Output+"/"+label+".png");yield return Frame();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/VariableBranchPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.GenericChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.LandChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.Payment.cs","Assets/Scripts/UI/ForgeBattlefieldController.Notices.cs","Assets/Scripts/UI/ForgeBattlefieldController.BattlefieldView.cs","Assets/Scripts/Networking/OnlineMatchSession.cs","Assets/Scripts/Networking/OnlineSpectatorView.cs"}.Select(p=>p+"\t"+Hash(p))));var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("VariableBranchValidation").AddComponent<ForgeBattlefieldController>();ui.StartCoroutine(Guard(ui));}
    static IEnumerator Guard(ForgeBattlefieldController ui){var stack=new Stack<IEnumerator>();stack.Push(Validate(ui));try{while(stack.Count>0){object c;try{var e=stack.Peek();if(!e.MoveNext()){(e as IDisposable)?.Dispose();stack.Pop();continue;}c=e.Current;if(c is IEnumerator nested){stack.Push(nested);continue;}}catch(Exception error){File.WriteAllText(Output+"/result.txt","FAIL "+error);throw;}yield return c;}File.WriteAllText(Output+"/result.txt","PASS: native Doodle choices in both seats, selected confirmation and source identity; native join-forces range/second payer, Vermin life enumeration/local draft and confirmation in three locales, exact option indices, stale/duplicate/nonacting gates, View/Return font stability, numeric/payment dock rectangles, native next-priority cleanup. Secret-choice projection and spectator filtering through OnlineMatchSession.Poll are adapters with archived native envelopes, not live-network or additional effect tests.");}finally{while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();Running=false;}}
    static IEnumerator Validate(ForgeBattlefieldController ui)
    {
        string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool input=module!=null&&module.enabled;if(module!=null)module.enabled=false;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None);var flags=notices.Select(n=>n.enabled).ToArray();foreach(var n in notices)n.enabled=false;
        try{foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
            int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale unavailable");yield return Frame();File.AppendAllText(Output+"/steps.log","requested="+lang+" loaded="+GamePreferences.Language+" revision="+GamePreferences.Revision+"\n");
            foreach(int actor in new[]{1,2})foreach(int count in new[]{0,1}){
                var v=Request("doodle-match",r=>r.kind=="ChooseOptions"&&r.seat==actor&&r.selectedCount==count);int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};ui.Present(null,actor,false,null,null,"");ui.Present(v,actor,true,submit,null,"");yield return Frame();Clean();
                Check(v.seat==actor,"Wrong native recipient");var panel=GameObject.Find("CardAbilityChoices");Check(panel!=null&&panel.transform.parent==Root,"Generic panel absent");var confirm=panel.transform.Find("GenericConfirm").GetComponent<Button>();Check(confirm.interactable==(count==1)&&ui.OptionIndex("cancel")<0,"Invented confirmation/cancellation");
                var choices=panel.GetComponentsInChildren<Button>().Where(b=>b.name.StartsWith("GenericOption_")).ToArray();Check(choices.Length==2,"Choice lost");Check(panel.GetComponentsInChildren<Text>().All(t=>!t.resizeTextForBestFit),"Auto font size");
                if(count==1){var selected=v.request.options.Single(o=>o.selected);Check(choices.Single(b=>b.name=="GenericOption_"+ui.OptionIndex(selected.id)).GetComponentInChildren<Text>().text.StartsWith("●"),"Native selection absent");}
                int[] fonts=panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();Check(panel.GetComponent<CanvasGroup>().alpha==0&&!panel.GetComponent<CanvasGroup>().blocksRaycasts,"Window not hidden");ui.RestoreBattlefieldWindows();yield return Frame();Check(fonts.SequenceEqual(panel.GetComponentsInChildren<Text>().Select(t=>t.fontSize))&&calls==0,"Restore changed text/submitted");
                var button=count==1?confirm:choices.Single(b=>b.name=="GenericOption_"+ui.OptionIndex(v.request.options.Single(o=>o.label.TrimEnd().EndsWith(" — Doodle")).id));int expected=count==1?ui.OptionIndex("confirm-cards"):ui.OptionIndex(v.request.options.Single(o=>o.label.TrimEnd().EndsWith(" — Doodle")).id);
                Check(!ui.TrySubmitPresentedOption(expected,v.request.requestId-1),"Stale choice accepted");yield return Shot(lang,"secret-seat-"+actor+"-selected-"+count);Click(button);Check(calls==1&&last==expected&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Choice ID/duplicate");
                ui.Present(v,actor,false,submit,null,"");yield return Frame();Check(panel.GetComponentsInChildren<Button>().All(b=>!b.interactable)&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Nonacting choice accepted");
                ui.Present(Read("doodle-match","resolved"+(actor==2?"-other":"")),actor,false,null,null,"");yield return Frame();Check(GameObject.Find("CardAbilityChoices")==null,"Generic picker retained");
            }
            foreach(var v in new[]{Request("join-forces",r=>r.kind=="ChooseNumber"&&r.seat==2&&r.selectedValue==0),Request("join-forces",r=>r.kind=="ChooseNumber"&&r.seat==2&&r.selectedValue==3)}){
                int actor=v.request.seat,calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};ui.Present(null,actor,false,null,null,"");ui.Present(v,actor,true,submit,null,"");yield return Frame();Clean();var dock=Root.Find("CornerCluster/ControlRow/CardAbilityChoices");Check(dock!=null&&dock.gameObject.activeInHierarchy,"Native range not docked");DockBounds(dock);Check(dock.Find("NumericValue").GetComponent<Text>().text==v.request.selectedValue.ToString(),"Native value differs");
                var action=dock.Find(v.request.selectedValue==0?"Increase":"ConfirmValue").GetComponent<Button>();int expected=ui.OptionIndex(v.request.selectedValue==0?"number-plus":"confirm-number");Check(!ui.TrySubmitPresentedOption(expected,v.request.requestId-1),"Stale number accepted");Click(action);Check(calls==1&&last==expected&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Native range index/duplicate");
                ui.Present(v,actor,false,submit,null,"");yield return Frame();Check(dock.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Viewer native range enabled");
            }
            var life=Request("vermin-repeat",r=>r.kind=="dialog"&&r.seat==2&&r.options.Length==31);int lifeCalls=0,lifeLast=-1;Action<int> lifeSubmit=i=>{lifeCalls++;lifeLast=i;};ui.Present(null,2,false,null,null,"");ui.Present(life,2,true,lifeSubmit,null,"");yield return Frame();Clean();var numeric=Root.Find("CornerCluster/ControlRow/CardAbilityChoices");Check(numeric.gameObject.activeInHierarchy,"Life enumeration absent");DockBounds(numeric);Check(!numeric.Find("Decrease").GetComponent<Button>().interactable,"Below native minimum");Click(numeric.Find("Increase").GetComponent<Button>());yield return Frame();Check(lifeCalls==0&&numeric.Find("NumericValue").GetComponent<Text>().text=="1","Enumeration must draft");yield return Shot(lang,"life-number-seat-two");Click(numeric.Find("ConfirmValue").GetComponent<Button>());Check(lifeCalls==1&&life.request.options[lifeLast].label=="1"&&!ui.TrySubmitPresentedOption(lifeLast,life.request.requestId),"Life exact option/duplicate");
            ui.Present(life,2,false,lifeSubmit,null,"");yield return Frame();Check(numeric.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Nonacting local range enabled");
            var confirmation=Request("vermin-repeat",r=>r.kind=="InputConfirm"&&r.seat==2);ui.Present(confirmation,2,true,lifeSubmit,null,"");yield return Frame();Clean();var yesNo=GameObject.Find("CardAbilityChoices");Check(yesNo!=null&&yesNo.transform.parent==Root&&((RectTransform)yesNo.transform).rect.height<200,"Life confirmation wrong panel");string title=yesNo.transform.Find("ValueTitle").GetComponent<Text>().text;Check(title==(lang=="zh-CN"?"支付 1 点生命？":lang=="ja-JP"?"1点のライフを支払いますか？":"Pay 1 life?"),"Life confirmation locale: requested="+lang+" loaded="+GamePreferences.Language+" title="+title);Click(yesNo.transform.Find("ValueOption_"+ui.OptionIndex("ok")).GetComponent<Button>());Check(lifeCalls==2&&lifeLast==ui.OptionIndex("ok"),"Life confirmation ID");
            var payment=Request("join-forces",r=>r.kind.Contains("PayMana")&&r.seat==2);int payCalls=0,payLast=-1;ui.Present(payment,2,true,i=>{payCalls++;payLast=i;},null,"");yield return Frame();Clean();var pay=Root.Find("CornerCluster/ControlRow/ManaPaymentActions");Check(pay.gameObject.activeInHierarchy,"Second payer dock absent");DockBounds(pay);yield return Shot(lang,"join-second-payer");Click(pay.Find("AutoPayment").GetComponent<Button>());Check(payCalls==1&&payLast==ui.OptionIndex("ok"),"Second payer auto-pay ID");ui.Present(payment,2,false,i=>payCalls++,null,"");yield return Frame();Check(pay.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Other-seat payment enabled");
            ui.Present(Read("join-forces","resolved-other"),2,false,null,null,"");yield return Frame();Check(!pay.gameObject.activeInHierarchy&&GameObject.Find("CardAbilityChoices")==null,"Payment/number retained after next priority");
        }
        yield return ProjectSecretRequests();
        }finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=input;for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=flags[i];}
    }
    static IEnumerator ProjectSecretRequests()
    {
        // Start a quiescent real session so Poll runs with its normal initialized state.
        // Feed archived envelopes only after it awaits input; never submit them to that engine.
        var deck=new DeckDefinition{cards=new List<DeckEntry>{new DeckEntry{setCode="10E",collectorNumber="376",count=60}}};
        using var session=new OnlineMatchSession("doodle-match",deck,deck,4);
        float deadline=Time.realtimeSinceStartup+55;while(!session.Ready&&session.Failure==null&&Time.realtimeSinceStartup<deadline){session.Poll();yield return null;}Check(session.Ready&&session.Failure==null,"Adapter session initialization");
        var queue=(ConcurrentQueue<string>)typeof(OnlineMatchSession).GetField("incoming",Hidden).GetValue(session);while(queue.TryDequeue(out _)){}
        string trace=Path.Combine(Folder("doodle-match"),"trace.jsonl");File.Copy(trace,Output+"/inputs/secret-native-trace.jsonl");File.AppendAllText(Output+"/input-hashes.tsv","secret-native-trace\t"+Hash(trace)+"\n");int tested=0;
        foreach(string line in File.ReadLines(trace)){var m=JsonUtility.FromJson<ForgeWireMessage>(line);if(m.type!="request"||m.request.kind!="ChooseOptions")continue;queue.Enqueue(line);Check(session.Poll()&&session.Failure==null,"Native envelope projection failed");int actor=m.request.seat;var act=session.GetView(actor).forge;var other=session.GetView(3-actor).forge;Check(act.awaitingInput&&act.request.requestId==m.request.requestId&&!HasRequest(other)&&!other.awaitingInput,"Secret options exposed to other seat");Check(other.players[actor-1].hand.Length==0,"Private hand leak");var spectator=session.GetView(3).forge;Check(!HasRequest(spectator)&&!spectator.awaitingInput&&spectator.players.All(p=>p.hand.Length==0),"Spectator request/hand leak");Check(!session.ApplyAction(new GameAction{type=GameActionType.ConfirmChoice,playerId=3-actor,sourceObjectId=m.request.requestId,optionId=0}).accepted,"Other seat submitted secret");Check(!session.ApplyAction(new GameAction{type=GameActionType.ConfirmChoice,playerId=actor,sourceObjectId=m.request.requestId-1,optionId=0}).accepted,"Stale secret action accepted");File.WriteAllText(Output+"/inputs/projected-secret-"+tested+".json",JsonUtility.ToJson(session.GetView(3-actor),true));tested++;}
        Check(tested==4,"Missing both seats and selected confirmation");File.WriteAllText(Output+"/projection-adapter.txt","PASS: four archived native envelopes through actual Poll; only actor receives request, nonactor/stale actions rejected, spectator options/private hands absent. No network transport or new effects claimed.");
    }
    // JsonUtility may create an empty nested DTO for an omitted/null field.
    static bool HasRequest(ForgeSeatView v)=>v.request!=null&&(v.request.requestId!=0||(v.request.options?.Length??0)>0||!string.IsNullOrEmpty(v.request.message));
}
